import android.app.Notification;
import android.app.NotificationChannel;
import android.app.NotificationManager;
import android.app.Service;
import android.content.Context;
import android.content.Intent;
import android.media.AudioAttributes;
import android.media.AudioFocusRequest;
import android.media.AudioManager;
import android.os.Build;
import android.os.Handler;
import android.os.IBinder;
import android.os.Looper;
import android.os.PowerManager;
import android.util.Log;

/**
 * Foreground media-playback service for DJ Sugar on Android.
 *
 * Why this exists: Android 8+ background-execution limits (and stricter
 * enforcement on Android 14+) suspend or kill audio when the app is
 * backgrounded or the screen turns off. The manifest already declared the
 * FOREGROUND_SERVICE / FOREGROUND_SERVICE_MEDIA_PLAYBACK permissions, but
 * no Service implementation consumed them, so they were inert.
 *
 * What it does: holds a foreground service (mediaPlayback type) plus a
 * partial wake lock and an audio-focus request while mixing, so background
 * playback survives screen-off and Home-swipe. On permanent audio-focus
 * loss (e.g. incoming call) it relinquishes foreground state and the wake
 * lock so the system can reclaim audio; on focus gain it re-acquires.
 *
 * Follow-up (requires C++ change, intentionally out of scope here): route
 * focus events into the engine via JNI (e.g. nativeAudioFocusChanged) so
 * LOSS pauses the mix and LOSS_TRANSIENT_CAN_DUCK ducks volume instead of
 * the coarse relinquish/re-acquire behavior below.
 */
public class PlaybackService extends Service {
    private static final String TAG = "DJSugarPlayback";
    private static final String CHANNEL_ID = "djsugar_playback";
    private static final int NOTIFICATION_ID = 1;
    // The wake lock is acquired with a timeout as a safety net against
    // battery drain if the service is ever orphaned, and renewed before it
    // expires for as long as the service holds it.
    private static final long WAKE_LOCK_TIMEOUT_MS = 10 * 60 * 1000L;
    private static final long WAKE_LOCK_RENEW_MS = 9 * 60 * 1000L;

    public static final String ACTION_START =
        "org.mixxx.action.START_PLAYBACK_SERVICE";
    public static final String ACTION_STOP =
        "org.mixxx.action.STOP_PLAYBACK_SERVICE";

    private PowerManager.WakeLock mWakeLock;
    private final Handler mHandler = new Handler(Looper.getMainLooper());
    private final Runnable mRenewWakeLock = new Runnable() {
        @Override
        public void run() {
            if (mWakeLock != null && mWakeLock.isHeld()) {
                // Re-acquiring a non-reference-counted lock resets its timeout.
                mWakeLock.acquire(WAKE_LOCK_TIMEOUT_MS);
                mHandler.postDelayed(this, WAKE_LOCK_RENEW_MS);
            }
        }
    };
    private AudioManager mAudioManager;
    private AudioFocusRequest mFocusRequest;
    private final AudioManager.OnAudioFocusChangeListener mFocusListener =
        new AudioManager.OnAudioFocusChangeListener() {
            @Override
            public void onAudioFocusChange(int focusChange) {
                switch (focusChange) {
                    case AudioManager.AUDIOFOCUS_LOSS:
                        // Permanent loss (call, alarm): give everything up so
                        // the system reclaims audio instead of mixing over it.
                        Log.i(TAG, "Audio focus lost permanently, relinquishing");
                        abandonAudioFocus();
                        releaseWakeLock();
                        stopForeground(true);
                        break;
                    case AudioManager.AUDIOFOCUS_GAIN:
                        Log.i(TAG, "Audio focus gained, re-acquiring");
                        acquireWakeLock();
                        requestAudioFocus();
                        startInForeground();
                        break;
                    case AudioManager.AUDIOFOCUS_LOSS_TRANSIENT:
                    case AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK:
                        // Coarse handling until the JNI engine hook exists:
                        // relinquish foreground priority, keep service alive.
                        Log.i(TAG, "Audio focus transient loss, standing down");
                        releaseWakeLock();
                        break;
                    default:
                        break;
                }
            }
        };

    /**
     * Starts (or re-asserts) the service. Call only while the activity is in
     * the foreground: on Android 12+ starting a foreground service from the
     * background throws ForegroundServiceStartNotAllowedException (a subclass
     * of IllegalStateException), and on 8+ startService from the background
     * throws IllegalStateException. Either is caught and logged.
     */
    public static void start(Context context) {
        Intent intent = new Intent(context, PlaybackService.class);
        intent.setAction(ACTION_START);
        try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                context.startForegroundService(intent);
            } else {
                context.startService(intent);
            }
        } catch (IllegalStateException e) {
            Log.w(TAG, "Could not start playback service", e);
        }
    }

    public static void stop(Context context) {
        // stopService is not subject to background-start restrictions.
        context.stopService(new Intent(context, PlaybackService.class));
    }

    @Override
    public void onCreate() {
        super.onCreate();
        mAudioManager = (AudioManager) getSystemService(Context.AUDIO_SERVICE);
        createNotificationChannel();
    }

    @Override
    public int onStartCommand(Intent intent, int flags, int startId) {
        if (intent != null && ACTION_STOP.equals(intent.getAction())) {
            abandonAudioFocus();
            releaseWakeLock();
            stopForeground(true);
            stopSelf();
            return START_NOT_STICKY;
        }
        acquireWakeLock();
        requestAudioFocus();
        startInForeground();
        // If the system kills us under memory pressure, recreate the service
        // (intent redelivered) so playback protection resumes.
        return START_STICKY;
    }

    @Override
    public void onDestroy() {
        abandonAudioFocus();
        releaseWakeLock();
        super.onDestroy();
    }

    @Override
    public IBinder onBind(Intent intent) {
        return null;
    }

    private void startInForeground() {
        Notification notification = buildNotification();
        try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                startForeground(NOTIFICATION_ID, notification,
                    android.content.pm.ServiceInfo
                        .FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);
            } else {
                startForeground(NOTIFICATION_ID, notification);
            }
        } catch (IllegalStateException e) {
            // ForegroundServiceStartNotAllowedException (Android 12+), e.g.
            // focus regained while the app is in the background.
            Log.w(TAG, "Could not enter foreground", e);
        }
    }

    private void createNotificationChannel() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
            return;
        }
        NotificationChannel channel = new NotificationChannel(
            CHANNEL_ID,
            "Playback",
            NotificationManager.IMPORTANCE_LOW);
        channel.setDescription("Keeps your mix playing in the background");
        NotificationManager manager =
            (NotificationManager) getSystemService(Context.NOTIFICATION_SERVICE);
        if (manager != null) {
            manager.createNotificationChannel(channel);
        }
    }

    private Notification buildNotification() {
        Notification.Builder builder;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            builder = new Notification.Builder(this, CHANNEL_ID);
        } else {
            builder = new Notification.Builder(this);
        }
        return builder
            .setContentTitle("DJ Sugar")
            .setContentText("Mixing — playback protected in background")
            .setSmallIcon(android.R.drawable.ic_media_play)
            .setOngoing(true)
            .build();
    }

    private void acquireWakeLock() {
        if (mWakeLock != null && mWakeLock.isHeld()) {
            return;
        }
        PowerManager powerManager =
            (PowerManager) getSystemService(Context.POWER_SERVICE);
        if (powerManager == null) {
            return;
        }
        mWakeLock = powerManager.newWakeLock(
            PowerManager.PARTIAL_WAKE_LOCK, TAG + ":lock");
        mWakeLock.setReferenceCounted(false);
        mWakeLock.acquire(WAKE_LOCK_TIMEOUT_MS);
        mHandler.removeCallbacks(mRenewWakeLock);
        mHandler.postDelayed(mRenewWakeLock, WAKE_LOCK_RENEW_MS);
    }

    private void releaseWakeLock() {
        mHandler.removeCallbacks(mRenewWakeLock);
        if (mWakeLock != null && mWakeLock.isHeld()) {
            mWakeLock.release();
        }
        mWakeLock = null;
    }

    private void requestAudioFocus() {
        if (mAudioManager == null) {
            return;
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            if (mFocusRequest == null) {
                AudioAttributes attributes = new AudioAttributes.Builder()
                    .setUsage(AudioAttributes.USAGE_MEDIA)
                    .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                    .build();
                mFocusRequest = new AudioFocusRequest.Builder(
                        AudioManager.AUDIOFOCUS_GAIN)
                    .setAudioAttributes(attributes)
                    .setOnAudioFocusChangeListener(mFocusListener)
                    .build();
            }
            mAudioManager.requestAudioFocus(mFocusRequest);
        } else {
            mAudioManager.requestAudioFocus(mFocusListener,
                AudioManager.STREAM_MUSIC, AudioManager.AUDIOFOCUS_GAIN);
        }
    }

    private void abandonAudioFocus() {
        if (mAudioManager == null) {
            return;
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O
            && mFocusRequest != null) {
            mAudioManager.abandonAudioFocusRequest(mFocusRequest);
        } else {
            mAudioManager.abandonAudioFocus(mFocusListener);
        }
    }
}

